<script setup lang="ts">
import { ref, watch } from 'vue'
import QRCode from 'qrcode'
import { buildInviteUrl } from '@/voice/inviteUrl'

const props = defineProps<{ code: string }>()
const image = ref('')
const link = ref('')
const error = ref('')

watch(() => props.code, async code => {
  image.value = ''
  error.value = ''
  if (!/^[A-Z0-9]{10}$/i.test(code)) return
  link.value = buildInviteUrl(code)
  try {
    const result = await QRCode.toDataURL(link.value, {
      width: 240,
      margin: 2,
      errorCorrectionLevel: 'M',
      color: { dark: '#111111', light: '#ffffff' },
    })
    if (props.code === code) image.value = result
  } catch {
    error.value = 'Der QR-Code konnte nicht erstellt werden.'
  }
}, { immediate: true })
</script>

<template>
  <details v-if="image || error" class="invite-qr" open>
    <summary>QR-Code für diesen Invite anzeigen</summary>
    <div v-if="image" class="qr-content">
      <img :src="image" alt="QR-Code mit Join-Link und PeerJS-Code" width="240" height="240" />
      <p>Mit einem normalen QR-Scanner öffnet sich dieser Link:</p>
      <a :href="link">{{ link }}</a>
    </div>
    <p v-else role="alert">{{ error }}</p>
  </details>
</template>

